Clase CajaFuerte
    Privado Definir clave Como Cadena;

    Metodo Constructor(unaClave Como Cadena)
        Este.clave <- unaClave;
    FinMetodo

    Publico Metodo Abrir(intento Como Cadena) Como Entero
        Si intento = Este.clave Entonces
            Retornar 1;
        SiNo
            Retornar 0;
        FinSi
    FinMetodo
FinClase

Proceso EjecutarCajaFuerte
    Definir clave Como Cadena;
    Definir intento Como Cadena;
    Definir caja Como CajaFuerte;
    Leer clave;
    Leer intento;
    caja <- Nuevo CajaFuerte(clave);
    Escribir caja.Abrir(intento);
FinProceso
